import Foundation

/// Pure privacy gate: concealed / transient / auto-generated markers and password manager sources.
struct ClipboardPrivacyFilter: Equatable, Sendable {
    /// Markers from the nspasteboard.org conventions that password managers and utilities set.
    static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// 1Password, Bitwarden, KeePassXC, Keychain Access and Apple Passwords.
    static let passwordManagerBundleIDs: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
    ]

    var blockedBundleIDs = Self.passwordManagerBundleIDs

    /// `true` when the change may be recorded.
    func allowsCapture(types: [String], frontmostBundleID: String?) -> Bool {
        if types.contains(where: Self.sensitiveTypes.contains) { return false }
        guard let frontmostBundleID else { return true }
        let lowered = frontmostBundleID.lowercased()
        return !blockedBundleIDs.contains { $0.lowercased() == lowered }
    }
}
